'use strict';
function renderHub(){document.getElementById("availability").textContent=`${ORION_MISSIONS.filter(m=>m.href).length} 個任務已開放 · ${ORION_MISSIONS.length} 個故事等待探索`;const earned=OrionProgress.read().sigils;document.getElementById('total').textContent=ORION_MISSIONS.filter(m=>earned.includes(m.sigil)).length;document.getElementById('sigils').innerHTML=ORION_MISSIONS.map(m=>`<div class="sigil ${earned.includes(m.sigil)?'earned':''}" aria-label="${m.sigilName}符印：${earned.includes(m.sigil)?'已收藏':'未收藏'}"><b aria-hidden="true">${m.symbol}</b>${m.sigilName}<br>${earned.includes(m.sigil)?'已收藏':'未收藏'}</div>`).join('');document.getElementById('missions').innerHTML=ORION_MISSIONS.map(m=>`<article class="mission ${m.href?'available':''}"><div class="mission-top"><span class="symbol" aria-hidden="true">${m.symbol}</span><span class="badge">${m.href?'已開放':'即將登場'}</span></div><h3>${m.title}</h3><p class="english">${m.english}</p><p class="story">${m.story}</p><div class="topic">${m.topic}</div><div class="card-footer"><span>${earned.includes(m.sigil)?'✦ 已收藏':m.sigilName+'符印'}</span>${m.href?`<a href="${m.href}">${earned.includes(m.sigil)?'再次探索':'開始任務'} ↗</a>`:'<span class="soon">準備中</span>'}</div></article>`).join('');}
renderHub();window.addEventListener('pageshow',renderHub);window.addEventListener('storage',renderHub);
